'use strict';
(async()=>{
 const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 try{
  const res=await fetch('data/raid-roster-validation.json');if(!res.ok)throw Error('Source analysis could not load');const db=await res.json();let selected;
  const c=db.counts;$('#roster-status').textContent=`Snapshot ${db.snapshot} · ${c.uniqueHeroes} unique + ${c.rareHeroes} rare heroes · ${c.loadouts} evolution/weapon combinations · ${c.sourceFiles} source files analyzed · ${c.tracedEventInputs} graph damage inputs resolved. ${c.resolvedActions??c.codeTracedActions} action names now have complete calculator models across their listed loadouts; ${c.codeTracedActions} are fully code-traced, ${c.estimatedActions} remain estimates and ${c.unresolvedActions} remain unresolved.`;
  function sourceDetails(r){const s=db.sources[r?.source];return s?`<details><summary>Source evidence: ${esc(r.source)}</summary><p class="fine">SHA-256: ${esc(s.sha256)} · ${s.lineCount} lines. These selected lines locate relevant behavior; they do not establish every branch.</p><pre style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(s.effectLines.map(l=>l.line+': '+l.text).join('\n')||'Graph evidence is represented by its nodes and connections below.')}</pre></details>`:'';}
  function loadout(){const l=selected.loadouts[Number($('#evidence-loadout').value)||0];$('#evidence-body').innerHTML='<h3>Attacks and skills</h3>'+l.actions.map(a=>{const r=db.actions[a.name]||{};return `<article class="buff-choice"><h4>${esc(a.name)}</h4><p>${esc(r.status)}.</p><p class="fine">Calculator: ${esc(a.validation||a.status)}. This label applies only to the documented component.</p>${(r.events||[]).map(e=>`<p><strong>Node ${esc(e.node)}: ${esc(e.manualProof?"Code-traced sequence component":e.status)}</strong>${e.coefficient!==undefined?' · coefficient '+e.coefficient:''}<br>${esc(e.manualProof||e.reason||e.scope)}</p>`).join('')}${sourceDetails(r)}</article>`;}).join('')+'<h3>Hero / equipment options and dependencies</h3>'+l.optionIds.map(id=>{const r=db.options[id]||{};return `<details><summary>${esc(r.name||id)} · ${esc(r.class||'Unknown')}</summary><p>${esc(r.status)}</p>${r.modelScope?`<p>${esc(r.modelScope)}</p>`:''}<a href="index.html?table=static-options&q=${id}">View option #${id}</a><pre style="white-space:pre-wrap">${esc(JSON.stringify(r.referencedBuffs||{},null,2))}</pre>${sourceDetails(r)}</details>`;}).join('');}
  function choose(id){selected=db.heroes.find(h=>h.origin===Number(id));if(!selected)return;$('#hero-evidence').hidden=false;$('#evidence-title').textContent=selected.name+' · '+selected.rarity;$('#evidence-loadout').innerHTML=selected.loadouts.map((l,i)=>`<option value="${i}">${esc(l.stage+' · '+l.weaponName+' · #'+l.heroId)}</option>`).join('');loadout();history.replaceState(null,'','?hero='+selected.origin);$('#hero-evidence').scrollIntoView({block:'start'});}
  function list(){const q=$('#roster-search').value.trim().toLowerCase(),rarity=$('#roster-rarity').value;const rows=db.heroes.filter(h=>(!rarity||h.rarity===rarity)&&(!q||(h.name+' '+h.internalName).toLowerCase().includes(q)));$('#roster-count').textContent=rows.length+' matching heroes';$('#roster-list').innerHTML=rows.map(h=>`<button data-hero="${h.origin}" style="margin:4px;display:inline-flex;align-items:center;gap:10px">${h.image?`<img loading="lazy" src="${esc(h.image.startsWith('data/')?h.image:'data/visual/'+h.image)}" alt="" width="38" height="38">`:''}${esc(h.name)} · ${h.rarity}</button>`).join('');}
  $('#roster-search').oninput=list;$('#roster-rarity').onchange=list;$('#evidence-loadout').onchange=loadout;$('#roster-list').onclick=e=>{const b=e.target.closest('[data-hero]');if(b)choose(b.dataset.hero);};list();const id=new URLSearchParams(location.search).get('hero');if(id)choose(id);
 }catch(e){$('#roster-status').textContent='Could not load validation results: '+e.message;}
})();
